                      <div class="voice-setting-row"><span><strong>Style</strong><small>Writing register</small></span><select id="voiceStyling"><option value="auto">Auto</option><option value="casual">Casual</option><option value="semi-casual">Semi-casual</option><option value="semi-formal">Semi-formal</option><option value="formal">Formal</option></select></div>
