                    <div class="model-quick-menu hidden" id="modelQuickMenu" aria-hidden="true">
                      <div class="model-quick-head"><strong>Models</strong><button type="button" id="modelQuickManage">Manage</button></div>
                      <input class="model-quick-search" id="modelQuickSearch" type="search" placeholder="Search models" autocomplete="off" spellcheck="false" />
                      <div class="model-quick-list" id="modelQuickList"></div>
                    </div>
